    const others = ids.filter((id) => !grouped.has(id)); if (others.length) { cats.push(['other', T('Other', 'أخرى'), others]); others.forEach((id) => { catOf[id] = 'other'; }); }
    const catName = (k) => (cats.find((c) => c[0] === k) || [k, k])[1];
