        const hay = (id) => normQ_(g.modules[id].title + ' ' + title_(g, id) + ' ' + (DESC[id] ? DESC[id].join(' ') : ''));
        const anyTitle = order.some((id) => words.every((w) => hay(id).includes(w)));
