      const nameEnInput = el('input', { class: 'jbo-input', placeholder: '(unchanged)' });
      const nameArInput = el('input', { class: 'jbo-input', placeholder: '(unchanged)' });
      const mgrInput = el('input', { class: 'jbo-input', placeholder: '(unchanged)' });
      const mgrWrap = attachEmployeeAutocomplete_(mgrInput, managerPool_);
      const statusCell = el('td', { class: 'jbo-status-pending', text: '—' });
