    const isNum = c.t === 'n' && typeof c.v === 'number';
    const isDate = c.t === 'd' || (isNum && c.z && XLSX.SSF.is_date(c.z));
    let s = c.w !== undefined ? String(c.w) : (c.v === undefined || c.v === null ? '' : String(c.v));
