        method: 'POST', url: url + '/api/log', timeout: 8000,
        headers: { 'Content-Type': 'application/json', 'X-Write-Key': sharedGet_('backendWriteKey', '') },
        data: JSON.stringify({ actor: sharedGet_('ownerLabel', '') || 'unknown', slug: currentSlug_(), entries: [{ module: MODULE_ID, rowKey: 'export', status: 'ok', message: S.rows.length + ' issue rows exported', at: new Date().toISOString() }] }),
        onload: () => {}, onerror: () => {}, ontimeout: () => {},
