      const numOpts = [['', T('— none —', '— لا يوجد —')]].concat(S.det.numericKeys.map((k) => [k, k]));
      const setF = (k) => (v) => { S.f[k] = v; gmSet_('gosiFieldMap', S.f); buildRows_(); render_(); };
