        const t = el('div', { class: 'jbo-tab' + (S.tab === k ? ' jbo-tab-active' : ''), text: l });
        t.addEventListener('click', () => { if (S.busy) return; S.tab = k; S.selected.clear(); S.notice = ''; S.statusFilter = 'open'; S.typeFilter = ''; render_(); });
