      return { isNew: false, skip: false, warnings: ['Response cannot be verified from the API body (documented gap) - re-check the employee record after running.'], body: { id: Number(row.id), new_joining_date: row.new_joining_date, reason: row.reason }, preview: { joining_date: ['(current unknown)', row.new_joining_date] } };
