  /** CONFIRMED read: data.employee.salary.basic_salary + data.employee.benefits (sibling array). */
  async function readEarnings_(empId) {
    const res = await apiGet_(`/v2/employees/${empId}`, { profile_tab: 'salary_and_financial' });
    const emp = res.data && res.data.data && res.data.data.employee;
    if (!res.ok || !emp || !emp.salary || emp.salary.basic_salary === undefined || emp.salary.basic_salary === null) return null;
    const nameOf = (b) => { const v = b.name !== undefined ? b.name : b.name_i18n; return v && typeof v === 'object' ? (v.en || v.ar || Object.values(v)[0]) : v; };
    const benefits = (Array.isArray(emp.benefits) ? emp.benefits : []).map((b) => {
      const out = {};
      if (b.id !== undefined && b.id !== null) out.id = b.id; // Jisr's own UI omits id for a new line - never send id:null
      out.benefit_type_id = b.benefit_type_id !== undefined ? b.benefit_type_id : b.type_id;
      out.name = nameOf(b);
      out.company_contribution = b.company_contribution !== undefined ? b.company_contribution : b.contribution;
      return out;
    });
    return { basic: emp.salary.basic_salary, benefits };
  }

  const SalaryIncrementModule = {
    key: 'salary_increment', label: 'Salary Increment', needsIdList: true, parallelOk: true, noRetry: true, picks: [{ col: 'employee (pick from list)', target: 'employee_id' }], sameKey: (p) => 'e' + p.body.employee_id,
    choices: { without_retroactive: { values: ['TRUE', 'FALSE'], strict: true } },
    editableHeaders: ['employee_id', 'new_basic_salary', 'effective_date', 'reason', 'without_retroactive'],
    readableHeaders: ['current_basic_salary', 'employee_code', 'employee_name', 'national_id'],
    get csvHeaders() { return this.editableHeaders.concat(this.readableHeaders); },
    async fetchAllForIds(employeeIds, dir, onProgress, shouldStop) {
      const rows = new Array(employeeIds.length); let done = 0;
      await pool_(employeeIds, 6, async (empId, k) => {
        const d = dir.byId[String(empId)] || {};
        let cur = '';
        try { const e = await readEarnings_(empId); cur = e ? e.basic : ''; } catch (e) { /* blank */ }
        rows[k] = { employee_id: empId, new_basic_salary: '', effective_date: '', reason: '', without_retroactive: '', current_basic_salary: cur, employee_code: d.code || '', employee_name: d.name || '', national_id: d.nid || '' };
        if (onProgress) onProgress(++done, employeeIds.length);
      }, shouldStop);
      return rows.filter(Boolean);
    },
    buildPlanForRow(row) {
      if (!row.employee_id || !row.new_basic_salary || !row.effective_date || !row.reason) return { skip: true, warnings: ['Missing employee_id/new_basic_salary/effective_date/reason - skipped.'] };
      return {
        skip: false, warnings: [],
        body: { employee_id: row.employee_id, basic_salary: row.new_basic_salary, benefits: null, earnings_action: 'appraisal', effective_date: toIsoDate_(row.effective_date), reason: row.reason, without_retroactive: toBool_(row.without_retroactive), sync_gosi: false },
        preview: { basic_salary: [row.current_basic_salary || '(unknown)', row.new_basic_salary], effective_date: ['-', toIsoDate_(row.effective_date)] },
      };
    },
    /** Fix #1: read the current allowances so they are sent back unchanged (the script sent benefits:[]). */
    async enrichPlan(p) {
      const e = await readEarnings_(p.body.employee_id).catch(() => null);
      if (!e) { p.skip = true; p.warnings = ['Could not read this employee\'s current allowances - NOT sent (sending none would wipe them).']; return; }
      p.body.benefits = e.benefits;
      p.preview.basic_salary[0] = e.basic;
      p.warnings.push('Allowances kept as they are: ' + (e.benefits.length ? e.benefits.map((b) => (b.name || 'allowance') + ' ' + b.company_contribution).join(', ') : 'none on file') + '.');
    },
    async applyPlan(plan) {
      const fresh = await readEarnings_(plan.body.employee_id).catch(() => null); // re-read right before writing
      if (!fresh) return { ok: false, reason: 'Could not re-read current allowances - not sent, to avoid wiping them.' };
      const res = await apiPost_(`/v2/finance/employees/${plan.body.employee_id}/earnings`, {
        basic_salary: plan.body.basic_salary, benefits: fresh.benefits, earnings_action: plan.body.earnings_action,
        effective_date: plan.body.effective_date, reason: plan.body.reason, without_retroactive: plan.body.without_retroactive, sync_gosi: plan.body.sync_gosi,
      });
      const verdict = writeSucceeded_(res);
      if (!verdict.ok) return { ok: false, reason: verdict.reason };
      if (res.data && res.data.data && res.data.data.gosi_error) return { ok: false, reason: 'Saved but GOSI sync reported an error: ' + JSON.stringify(res.data.data.gosi_error) };
      return { ok: true, reason: null };
    },
  };

