      const v = writeSucceeded_(await apiPost_(`/v2/employees/${plan.body.employee_id}/employee_information/compensation_changes`, {
        compensation_changes: {
          compensation_changeset: { gosi_configuration: { value: plan.body.gosi_configuration_value, gosi_applicable_amount: plan.body.gosi_applicable_amount } },
          effective_date: plan.body.effective_date, reason: plan.body.reason,
        },
        without_retroactive: false,
      }));
